**Instalação do Node.js e o Mongoose**

### Passo 1: Instalar Node.js e Mongoose

```bash
# Instale Node.js e Mongoose
npm init -y
npm install mongoose
```

### Passo 2: Configurar o Mongoose

```javascript
// Criar um arquivo `mongoose.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const mongoose = require('mongoose');

mongoose.connect('mongodb://localhost:27017/mydatabase', { useNewUrlParser: true, useUnifiedTopology: true });
```

### Passo 3: Criar um Banco de Dados

```javascript
// Criar um arquivo `schema.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const mongoose = require('mongoose');

const dbConfig = {
  uri: 'mongodb://localhost:27017/mydatabase',
  useNewUrlParser: true,
  useUnifiedTopology: true,
};

module.exports = mongoose.createDatabase(dbConfig);
```

### Passo 4: Criar um Modelo

```javascript
// Criar um arquivo `models/user.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  nome: String,
  email: String,
  senha: String,
});

module.exports = mongoose.model('User', userSchema);
```

### Passo 5: Criar um Banco de Dados

```javascript
// Criar um arquivo `app.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const express = require('express');
const mongoose = require('./models/user');
const app = express();

// Iniciar o servidor
const port = 3000;
app.listen(port, () => {
  console.log(`Servidor rodando no port ${port}`);
});
```

### Passo 6: Criar Endpoints

```javascript
// Criar um arquivo `routes/user.js` no diretório raiz do projeto
// e adicione o seguinte conteúdo:
const express = require('express');
const router = express.Router();
const User = require('./models/user');

router.get('/users', async (req, res) => {
  try {
    const users = await User.find();
    res.json(users);
  } catch (err) {
    res.status(500).json({ message: 'Erro ao recuperar usuários' });
  }
});

router.post('/users', async (req, res) => {
  try {
    const user = new User(req.body);
    await user.save();
    res.json(user);
  } catch (err) {
    res.status(500).json({ message: 'Erro ao criar usuário' });
  }
});

module.exports = router;
```

### Passo 7: Iniciar o Servidor

```javascript
// Iniciar o servidor
const port = 3001;
app.use(express.json());
app.use('/api', router);
app.listen(port, () => {
  console.log(`Servidor rodando no port ${port}`);
});
```

